def lit_of(k, rng):
    if k=='int': return ['lit', rng.randint(-10,10)]
    if k=='text': return ['lit', rng.choice(['','a','bc','xyz','hello'])]
    if k=='bool': return ['lit', rng.choice([True,False])]
