class Gen:
    def __init__(self, rng, cells):
        self.rng=rng
        self.bounds={c:frozenset(t) for c,t in cells.items()}
        self.counter=0
    def fresh(self):
        self.counter+=1
        return 'v%d'%self.counter

    # type rep: ('s', frozenset) or ('f', result_type, frozenset(writes))
    def gen_scalar(self, k, env, facts, depth):
        # returns expr with static type exactly {k}
        rng=self.rng
        opts=['lit']
        for n,t in env.items():
            if t[0]=='s' and t[1]==frozenset([k]): opts.append(('var',n))
        for c in facts:
            if facts[c]==frozenset([k]): opts.append(('get',c))
        if depth>0:
            opts += ['rec']*4
        o=rng.choice(opts)
        if o=='lit': return lit_of(k,rng)
        if isinstance(o,tuple):
            return [o[0],o[1]]
        # recursive
        if k=='int':
            return ['add', self.gen_scalar('int',env,facts,depth-1), self.gen_scalar('int',env,facts,depth-1)]
        if k=='text':
            return ['cat', self.gen_scalar('text',env,facts,depth-1), self.gen_scalar('text',env,facts,depth-1)]

